// Generates packages/sim/src/data/{tables,glyphs}.ts from the JSON dump of
// tools/extract/dump_tables.cpp. Do not edit the generated files by hand.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const [jsonPath, hashPath] = process.argv.slice(2);
const tables = JSON.parse(readFileSync(jsonPath, 'utf8'));
const cppHash = readFileSync(hashPath, 'utf8').match(/hash ([0-9a-f]{8})/)[1];

// graphics/text.cpp: g_charTraits is file-local in reSL => parsed from the source
const textCpp = readFileSync(join(ROOT, 'reference/reSL/src/graphics/text.cpp'), 'utf8');
const traitsBody = textCpp.match(/g_charTraits\[256\]\s*=\s*\{([^}]*)\}/)[1];
const charTraits = traitsBody.split(',').map((s) => s.trim()).filter(Boolean).map((s) => Number(s));
if (charTraits.length !== 256) throw new Error(`g_charTraits: expected 256 values, got ${charTraits.length}`);

const LOGIC_KEYS = [
  'allowedRailCursorTypes', 'carriageYBiases', 'chunkBoundingBoxes', 'entranceRails', 'entranceColors',
  'movementPaths', 'railConnectionBiases', 'railConnectionRules', 'railTypeMeta', 'semaphoreGlyphBiases',
  'trainSpecifications', 'trainGlyphSizes', 'textGlyphs',
];
const keys = Object.keys(tables);
const glyphKeys = keys.filter((k) => !LOGIC_KEYS.includes(k));
for (const k of LOGIC_KEYS) if (!(k in tables)) throw new Error(`missing table ${k}`);

const header = (what) => `// Generated by tools/extract (pnpm extract) from reference/reSL — do not edit.
// ${what}
`;

function emit(keysToEmit) {
  return keysToEmit.map((k) => `export const ${k} = ${JSON.stringify(tables[k])} as const;\n`).join('');
}

const outDir = join(ROOT, 'packages/sim/src/data');
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'tables.ts'),
  header('Game logic tables (src/game/resources/*.cpp, graphics/text.cpp g_charTraits).') +
  `\n/** FNV-1a hash of all tables (logic and glyphs) as computed by dump_tables.cpp */\nexport const CPP_TABLES_HASH = 0x${cppHash};\n` +
  `/** Order of tables in the C++ dump (the hash covers all of them in this order) */\nexport const TABLE_ORDER = ${JSON.stringify(keys)} as const;\n\n` +
  emit(LOGIC_KEYS) +
  `\n/** graphics/text.cpp g_charTraits (1d7d:2969) */\nexport const charTraits = ${JSON.stringify(charTraits)} as const;\n`);
writeFileSync(join(outDir, 'glyphs.ts'), header('Bitmaps (presentation only).') + '\n' + emit(glyphKeys));
console.log(`wrote tables.ts (${LOGIC_KEYS.length} tables) and glyphs.ts (${glyphKeys.length} tables)`);
